def transform(grid):
    rows, cols = [0, 7, 14, 21, 28], [0, 11, 22]
    out = []
    for r in range(4):
        row = []
        for c in range(2):
            corners = [grid[rows[r]][cols[c]], grid[rows[r]][cols[c+1]],
                       grid[rows[r+1]][cols[c]], grid[rows[r+1]][cols[c+1]]]
            marks = [v for v in corners if v not in (3, 9)]
            if marks:
                row.append(max(set(marks), key=marks.count))
            else:
                row.append(9)
        out.append(row)
    return out
